// Ofertas, chat privado y valoración. No bloquean la sesión ni otras operaciones.
(()=>{
 const auth=window.RescateAuth, txt=(tag,t)=>{const el=document.createElement(tag);el.textContent=t;return el;};
 const api=(url,body)=>auth.api('/seguimiento'+url,body===undefined?{cache:'no-store'}:{method:'POST',body:JSON.stringify(body)});
 const panel=document.createElement('dialog');panel.className='panel-organizacion panel-seguimiento';panel.innerHTML='<header><h2 data-titulo></h2><button type="button" data-cerrar aria-label="Cerrar">×</button></header><p data-aviso role="status"></p><div data-contenido></div>';document.body.append(panel);
 const cont=panel.querySelector('[data-contenido]'),aviso=panel.querySelector('[data-aviso]');let version=0,modo='',chatId=null,ocupado=false,necesidadNueva=null,recordando=false;
 const button=(t,fn)=>{const b=txt('button',t);b.type='button';b.onclick=async()=>{if(ocupado)return;ocupado=true;b.disabled=true;aviso.textContent='';try{await fn();}catch(e){aviso.textContent=e.message;}finally{ocupado=false;b.disabled=false;}};return b;};
 const label=(t,el)=>{const l=txt('label',t);l.append(el);return l;};
 const refrescar=()=>Promise.allSettled([Promise.resolve().then(()=>auth.syncDonations()),Promise.resolve().then(()=>auth.refreshNotifications()),Promise.resolve().then(()=>window.RescateEntregas?.actualizar())]);
 function abrir(t,m){if(!auth.requireAuth())return false;version++;modo=m;panel.classList.toggle('panel-chat-compacto',m==='chat');chatId=null;cont.replaceChildren();aviso.textContent='';panel.querySelector('[data-titulo]').textContent=t;document.getElementById('odsDropdown')?.classList.remove('activo');if(!panel.open)panel.showModal();return true;}
 const vigente=v=>v===version&&panel.open;
 window.addEventListener('storage',e=>{if(['rescatepy_token','rescatepy_usuario'].includes(e.key)&&panel.open)panel.close();});
 async function ofrecer(n,seleccion){if(auth.getUser()?.tipoCuenta!=='DONANTE'||!abrir('Tengo este excedente','ofrecer'))return;const v=version;cont.append(txt('p',`${n.NOMBRE_ORGANIZACION} necesita ${n.ALIMENTO} · ${n.CANTIDAD} ${n.UNIDAD}`));
 try{const lotes=await api('/lotes');if(!vigente(v))return;const publicar=button('Publicar un nuevo lote para esta necesidad',()=>{panel.close();document.getElementById('abrirDonacionBtn')?.click();necesidadNueva={n,uid:auth.getUser()?.id};const alimento=document.getElementById('foodName'),cantidad=document.getElementById('foodQuantity'),unidad=document.getElementById('foodUnit');if(alimento)alimento.value=n.ALIMENTO;if(cantidad)cantidad.value=n.CANTIDAD;if(unidad&&[...unidad.options].some(o=>o.value===n.UNIDAD))unidad.value=n.UNIDAD;});
 if(!lotes.length){cont.append(txt('p','Primero registrá un lote apto para ofrecerlo a esta organización.'),publicar);return;}
 const select=document.createElement('select');for(const l of lotes){const o=txt('option',`${l.FOOD} · ${l.QUANTITY} ${l.UNIT}`);o.value=l.ID;select.append(o);}if(seleccion&&[...select.options].some(o=>String(o.value)===String(seleccion)))select.value=seleccion;else {const similar=lotes.find(l=>String(l.FOOD).trim().toLowerCase()===String(n.ALIMENTO).trim().toLowerCase());if(similar)select.value=similar.ID;}const mensaje=document.createElement('textarea');mensaje.maxLength=500;mensaje.rows=3;cont.append(label('Elegí el lote que querés ofrecer',select),label('Mensaje para la organización (opcional)',mensaje),button('Enviar oferta',async()=>{const d=await api('/ofertas',{necesidadId:Number(n.ID),donacionId:Number(select.value),mensaje:mensaje.value});if(vigente(v)){cont.replaceChildren(txt('p',d.mensaje),button('Ver mis ofertas',ofertas));}await refrescar();}),publicar);
 }catch(e){if(vigente(v)){aviso.textContent=e.message;cont.append(button('Reintentar consulta',()=>ofrecer(n,seleccion)));}}}
 async function ofertas(){const rol=auth.getUser()?.tipoCuenta;if(!rol||!abrir(rol==='ORGANIZACION'?'Ofertas recibidas':'Mis ofertas enviadas','ofertas'))return;const v=version;try{const filas=await api('/ofertas');if(!vigente(v))return;if(!filas.length)cont.append(txt('p','No hay ofertas registradas.'));for(const f of filas){const a=document.createElement('article');a.append(txt('h3',`${f.FOOD} · ${f.QUANTITY} ${f.UNIT}`),txt('p',rol==='DONANTE'?f.NOMBRE_ORGANIZACION:f.DONANTE),txt('p',`Necesidad: ${f.ALIMENTO} · ${f.NECESIDAD_CANTIDAD} ${f.NECESIDAD_UNIDAD}`),txt('p',`Estado: ${f.ESTADO}`));if(f.MENSAJE)a.append(txt('p',f.MENSAJE));if(rol==='ORGANIZACION'&&f.ESTADO==='PENDIENTE'){const fecha=document.createElement('input');fecha.type='datetime-local';fecha.required=true;fecha.min=window.RescateEntregas.local(Date.now()).slice(0,10)+'T00:00';fecha.value=window.RescateEntregas.local(Date.now()+3600000);if(f.LOTE_ESTADO==='ACTIVA'&&f.NECESIDAD_ESTADO==='ACTIVA')a.append(label('Proponer fecha y hora de retiro (Paraguay)',fecha),button('Aceptar donativo',async()=>{if(!fecha.reportValidity())return;await api(`/ofertas/${f.ID}/responder`,{respuesta:'SI',fechaRetiro:window.RescateEntregas.convertir(fecha.value)});await refrescar();if(vigente(v))await ofertas();}));else a.append(txt('p','El lote o la necesidad ya no está disponible.'));a.append(button('Rechazar',async()=>{await api(`/ofertas/${f.ID}/responder`,{respuesta:'NO'});await refrescar();if(vigente(v))await ofertas();}));}if(f.RESERVA_ID)a.append(txt('p',`Entrega: ${f.ENTREGA_RESULTADO||f.RESERVA_ESTADO||'PENDIENTE'}`),button('Abrir chat de entrega',()=>chat(f.RESERVA_ID,ofertas)));cont.append(a);}}catch(e){if(vigente(v))aviso.textContent=e.message;}}
 // Chat persistente de una reserva; no bloquea otras funcionalidades.
 async function chat(id,volver){if(!abrir('Chat de coordinación','chat'))return;chatId=Number(id);const v=version;
 const lista=document.createElement('div');lista.className='seguimiento-chat';lista.setAttribute('role','log');lista.setAttribute('aria-live','polite');
 const input=document.createElement('textarea');input.className='chat-mensaje';input.setAttribute('aria-label','Mensaje de coordinación');input.rows=3;input.maxLength=1000;input.placeholder='Escribí tu mensaje';let firma=null,cargando=false;
 async function cargar(){if(cargando||!vigente(v))return;cargando=true;try{const filas=await api(`/chat/${id}`);if(!vigente(v))return;aviso.textContent='';const f=JSON.stringify(filas);if(f===firma)return;firma=f;lista.replaceChildren();for(const m of filas){const propio=Number(m.AUTOR_ID)===Number(auth.getUser()?.id);const a=document.createElement('article');a.className=propio?'chat-propio':'chat-ajeno';a.append(txt('strong',propio?'Vos':m.NOMBRE),txt('p',m.MENSAJE),txt('small',new Date(m.CREADO_EN).toLocaleString('es-PY',{timeZone:'America/Asuncion'})));lista.append(a);}if(!filas.length)lista.textContent='Todavía no hay mensajes.';lista.scrollTop=lista.scrollHeight;}catch(e){if(vigente(v))aviso.textContent='No se pudo cargar el chat. '+e.message;}finally{cargando=false;}}
 const enviar=button('Enviar mensaje',async()=>{const mensaje=input.value.trim();if(!mensaje)throw new Error('Escribí un mensaje.');const respuesta=await api(`/chat/${id}`,{mensaje});if(vigente(v)){if(input.value.trim()===mensaje)input.value='';await cargar();input.focus();if(respuesta.notificado===false)aviso.textContent=respuesta.mensaje;}await refrescar();});
 input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();enviar.click();}});
 cont.append(txt('p','Conversación privada entre donante y organización.'),lista,label('Mensaje',input),enviar,button('Actualizar chat',cargar),button('Fecha y hora / confirmar recepción',()=>{panel.close();window.RescateEntregas.abrir();}));
 if(volver)cont.append(button('Volver',()=>{if(volver===ofertas||volver===conversaciones)return volver();panel.close();volver();}));
 input.focus();await cargar();const timer=setInterval(()=>{if(!vigente(v)){clearInterval(timer);return;}cargar();},5000);}
 // Bandeja de conversaciones de las reservas del usuario.
 async function conversaciones(){if(!abrir('Mis conversaciones','conversaciones'))return;const v=version;try{const filas=await api('/chats');if(!vigente(v))return;if(!filas.length)cont.append(txt('p','Todavía no hay conversaciones. Abrí un chat desde una reserva.'));for(const f of filas){const a=document.createElement('article');a.append(txt('strong',f.FOOD),txt('p',f.CONTRAPARTE),button('Abrir conversación',()=>chat(f.RESERVA_ID,conversaciones)));cont.append(a);}cont.append(button('Actualizar conversaciones',conversaciones));}catch(e){if(vigente(v))aviso.textContent=e.message;}}
 async function valorar(){if(!abrir('Calificar RescatePY','valorar'))return;const v=version;
 // Mostrar el formulario sin depender de la consulta inicial.
 const select=()=>{const el=document.createElement('select');const p=txt('option','Elegí una calificación');p.value='';el.append(p);for(let i=1;i<=5;i++){const o=txt('option',`${i} de 5`);o.value=i;el.append(o);}return el;};const p=select(),e=select(),c=document.createElement('textarea');c.maxLength=1000;c.rows=3;let editado=false;for(const campo of [p,e,c])campo.addEventListener('input',()=>{editado=true;});
 cont.append(label('Calidad de la plataforma',p),label('Experiencia con RescatePY',e),label('Comentario (opcional)',c),button('Guardar calificación',async()=>{if(!p.value||!e.value)throw new Error('Seleccioná las dos calificaciones.');editado=true;const r=await api('/calificacion',{plataforma:Number(p.value),experiencia:Number(e.value),comentario:c.value});if(vigente(v))aviso.textContent=r.mensaje;}));
 try{const datos=await api('/calificacion');if(vigente(v)&&!editado){p.value=datos.PLATAFORMA||'';e.value=datos.EXPERIENCIA||'';c.value=datos.COMENTARIO||'';}}catch(e){if(vigente(v)&&!editado)aviso.textContent='No se pudo cargar tu calificación anterior. Podés completar el formulario. '+e.message;}}

 panel.querySelector('[data-cerrar]').onclick=()=>panel.close();panel.addEventListener('close',()=>{version++;modo='';chatId=null;cont.replaceChildren();});
 function roles(){const r=auth.getUser()?.tipoCuenta;const ayuda=document.getElementById('abrirAyudarBtn');if(ayuda)ayuda.classList.toggle('campo-oculto',r==='DONANTE');const ofertasBtn=document.getElementById('ofertasSeguimientoBtn');if(ofertasBtn){ofertasBtn.classList.toggle('campo-oculto',!['DONANTE','ORGANIZACION'].includes(r));ofertasBtn.querySelector('[data-texto]').textContent=r==='ORGANIZACION'?'Ofertas recibidas':'Mis ofertas enviadas';}document.getElementById('calificarSeguimientoBtn')?.classList.toggle('campo-oculto',!['DONANTE','ORGANIZACION'].includes(r));}
 document.getElementById('ofertasSeguimientoBtn')?.addEventListener('click',ofertas);document.getElementById('calificarSeguimientoBtn')?.addEventListener('click',valorar);async function recordatorios(){if(recordando||auth.getUser()?.tipoCuenta!=='DONANTE')return;recordando=true;try{const r=await api('/recordatorios',{});if(r.generados)await auth.refreshNotifications();}catch(e){console.warn('Recordatorios:',e.message);}finally{recordando=false;}}
 document.addEventListener('rescate:sesion',()=>{if(panel.open)panel.close();necesidadNueva=null;roles();recordatorios();});roles();recordatorios();setInterval(recordatorios,60000);
 window.RescateSeguimiento={ofrecer,ofertas,chat,valorar,conversaciones,cancelarNueva:()=>{necesidadNueva=null;},trasPublicar:(lote,contenedor)=>{const contexto=necesidadNueva;if(!contexto||contexto.uid!==auth.getUser()?.id||!lote?.id||!contenedor)return;necesidadNueva=null;const b=button(`Ofrecer este lote a ${contexto.n.NOMBRE_ORGANIZACION}`,()=>{window.cerrarModalDonacion?.();return ofrecer(contexto.n,lote.id);});contenedor.append(b);}};
})();
